'use client'

import { unstable_ViewTransition as ViewTransition } from 'react'
import { usePathname } from 'next/navigation'
import { useEffect, useState } from 'react'

interface PageTransitionProps {
  children: React.ReactNode
}

export function PageTransition({ children }: PageTransitionProps) {
  const pathname = usePathname()
  const [direction, setDirection] = useState<'forward' | 'back'>('forward')
  const [previousPathname, setPreviousPathname] = useState(pathname)

  useEffect(() => {
    // Determine navigation direction based on path depth
    if (pathname !== previousPathname) {
      const isGoingDeeper = pathname.split('/').length > previousPathname.split('/').length
      const isComingBack = pathname === '/' && previousPathname.startsWith('/product/')

      setDirection(isGoingDeeper || !isComingBack ? 'forward' : 'back')
      setPreviousPathname(pathname)
    }
  }, [pathname, previousPathname])

  return (
    <ViewTransition name={`page-${direction}`}>
      {children}
    </ViewTransition>
  )
}

